m.def("trexio_write_state_file_name", [](TrexioHandle* h, const nb::object& arr, int32_t max_str_len) -> int {
  if (!h || !h->open()) return static_cast<int>(TREXIO_FAILURE);
  std::vector<std::string> strs;
  for (const auto& x : arr) strs.push_back(nb::cast<std::string>(x));
  std::vector<const char*> cs; cs.reserve(strs.size());
  for (const auto& s : strs) cs.push_back(s.c_str());
  return static_cast<int>(trexio_write_state_file_name(h->raw(), cs.data(), max_str_len > 0 ? max_str_len : static_cast<int32_t>(1)));
}, nb::arg("handle"), nb::arg("data"), nb::arg("max_str_len"));
